{"command":"cat <<'EOF' > /tmp/test_git_ops.c
#include <git2.h>
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    git_libgit2_init();
    git_repository *repo = NULL;
    const char *path = argv[1];
    const char *summary = argv[2];

    int err = git_repository_open(&repo, path);
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_libgit2_shutdown();
        return 0;
    }

    // Stage README.md
    git_index *index = NULL;
    err = git_repository_index(&index, repo);
    if (err == 0) {
        err = git_index_add_bypath(index, "README.md");
        if (err == 0) {
            err = git_index_write(index);
        }
    }
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_index_free(index);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return 0;
    }

    // Write tree
    git_oid tree_id;
    err = git_index_write_tree(&tree_id, index);
    git_index_free(index);
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_repository_free(repo);
        git_libgit2_shutdown();
        return 0;
    }

    git_tree *tree = NULL;
    err = git_tree_lookup(&tree, repo, &tree_id);
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_repository_free(repo);
        git_libgit2_shutdown();
        return 0;
    }

    // Get signature
    git_signature *sig = NULL;
    err = git_signature_default(&sig, repo);
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_tree_free(tree);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return 0;
    }

    // Get HEAD parent commit if exists
    git_commit *parent = NULL;
    git_reference *head_ref = NULL;
    int parent_count = 0;
    const git_commit *parents[1];

    if (git_repository_head(&head_ref, repo) == 0) {
        if (git_reference_peel((git_object **)&parent, head_ref, GIT_OBJECT_COMMIT) == 0) {
            parents[0] = parent;
            parent_count = 1;
        }
    }

    git_oid commit_id;
    err = git_commit_create(&commit_id, repo, "refs/heads/main", sig, sig, NULL, summary, tree, parent_count, parents);

    if (parent) git_commit_free(parent);
    if (head_ref) git_reference_free(head_ref);
    git_signature_free(sig);
    git_tree_free(tree);

    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_repository_free(repo);
        git_libgit2_shutdown();
        return 0;
    }

    // Set HEAD to refs/heads/main
    git_repository_set_head(repo, "refs/heads/main");

    printf("Added and committed!\n");
    printf("Pushing your new idea..\n");
    fflush(stdout);

    // Push to origin
    git_remote *remote = NULL;
    err = git_remote_lookup(&remote, repo, "origin");
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
        git_repository_free(repo);
        git_libgit2_shutdown();
        return 0;
    }

    const char *refspec = "refs/heads/main:refs/heads/main";
    git_strarray refspecs = { (char **)&refspec, 1 };
    git_push_options push_opts;
    git_push_options_init(&push_opts, GIT_PUSH_OPTIONS_VERSION);

    err = git_remote_push(remote, &refspecs, &push_opts);
    if (err < 0) {
        const git_error *e = git_error_last();
        fprintf(stderr, " ERROR eureka > %s\n", e ? e->message : "git error");
    } else {
        printf("Pushed!\n");
    }

    git_remote_free(remote);
    git_repository_free(repo);
    git_libgit2_shutdown();
    return 0;
}
EOF
