    const git_error *e = git_error_last();
    const char *msg = e ? e->message : "";
    int klass = e ? e->klass : 0;

    const char *klass_str = "Unknown";
    switch (klass) {
        case 1: klass_str = "None"; break;
        case 2: klass_str = "Os"; break;
        case 3: klass_str = "Invalid"; break;
        case 4: klass_str = "Reference"; break;
        case 5: klass_str = "Zlib"; break;
        case 6: klass_str = "Repository"; break;
        case 7: klass_str = "Config"; break;
        case 8: klass_str = "Regex"; break;
