static void format_err(char *err_buf, size_t err_buf_size, int code) {
    const git_error *e = git_error_last();
    const char *msg = e ? e->message : "";
    int klass = e ? e->klass : 0;

    const char *klass_str = "Unknown";
    switch (klass) {
        case 1: klass_str = "None"; break;
        case 2: klass_str = "Os"; break;
        case 3: klass_str = "Invalid"; break;
        case 4: klass_str = "Reference"; break;
        case 5: klass_str = "Zlib"; break;
        case 6: klass_str = "Repository"; break;
        case 7: klass_str = "Config"; break;
        case 8: klass_str = "Regex"; break;
        case 9: klass_str = "Odb"; break;
        case 10: klass_str = "Index"; break;
        case 11: klass_str = "Object"; break;
        case 12: klass_str = "Net"; break;
        case 13: klass_str = "Tag"; break;
        case 14: klass_str = "Tree"; break;
        case 15: klass_str = "Indexer"; break;
        case 16: klass_str = "Ssl"; break;
        case 17: klass_str = "Ssh"; break;
        case 18: klass_str = "Callback"; break;
        case 19: klass_str = "Cherrypick"; break;
        case 20: klass_str = "Describe"; break;
        case 21: klass_str = "Rebase"; break;
        case 22: klass_str = "Filesystem"; break;
        case 23: klass_str = "Patch"; break;
        case 24: klass_str = "Worktree"; break;
        case 25: klass_str = "SHA1"; break;
        case 26: klass_str = "Http"; break;
        case 27: klass_str = "Internal"; break;
    }

    const char *code_str = "Unknown";
    switch (code) {
        case 0: code_str = "Ok"; break;
        case -1: code_str = "GenericError"; break;
        case -3: code_str = "NotFound"; break;
        case -4: code_str = "Exists"; break;
        case -5: code_str = "Ambiguous"; break;
        case -6: code_str = "BufSize"; break;
        case -7: code_str = "User"; break;
        case -8: code_str = "BareRepo"; break;
        case -9: code_str = "UnbornBranch"; break;
        case -10: code_str = "Unmerged"; break;
        case -11: code_str = "NonFastForward"; break;
        case -12: code_str = "InvalidSpec"; break;
        case -13: code_str = "Conflict"; break;
        case -14: code_str = "Locked"; break;
        case -15: code_str = "Modified"; break;
        case -16: code_str = "Auth"; break;
        case -17: code_str = "Certificate"; break;
        case -18: code_str = "Applied"; break;
        case -19: code_str = "Peel"; break;
        case -20: code_str = "Eof"; break;
        case -21: code_str = "Invalid"; break;
        case -22: code_str = "Uncommitted"; break;
        case -23: code_str = "Directory"; break;
        case -24: code_str = "MergeConflict"; break;
        case -25: code_str = "Passthrough"; break;
        case -26: code_str = "IterOver"; break;
        case -27: code_str = "Retry"; break;
        case -28: code_str = "Mismatch"; break;
        case -29: code_str = "IndexDirty"; break;
        case -30: code_str = "ApplyFail"; break;
    }

    snprintf(err_buf, err_buf_size, "%s; class=%s (%d); code=%s (%d)", msg, klass_str, klass, code_str, code);
}

int do_git_ops(const char *repo_path, const char *summary, char *err_buf, size_t err_buf_size) {
    git_libgit2_init();

    git_repository *repo = NULL;
    int err = git_repository_open(&repo, repo_path);
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_libgit2_shutdown();
        return err;
    }

    // Stage README.md
    git_index *index = NULL;
    err = git_repository_index(&index, repo);
    if (err == 0) {
        err = git_index_add_bypath(index, "README.md");
        if (err == 0) {
            err = git_index_write(index);
        }
    }
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        if (index) git_index_free(index);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    // Write tree
    git_oid tree_id;
    err = git_index_write_tree(&tree_id, index);
    git_index_free(index);
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    git_tree *tree = NULL;
    err = git_tree_lookup(&tree, repo, &tree_id);
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    // Get signature
    git_signature *sig = NULL;
    err = git_signature_default(&sig, repo);
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_tree_free(tree);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    // Parent commit
    git_commit *parent = NULL;
    git_reference *head_ref = NULL;
    int parent_count = 0;
    const git_commit *parents[1];

    err = git_repository_head(&head_ref, repo);
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_signature_free(sig);
        git_tree_free(tree);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    err = git_reference_peel((git_object **)&parent, head_ref, GIT_OBJECT_COMMIT);
    if (err == 0) {
        parents[0] = parent;
        parent_count = 1;
    } else {
        format_err(err_buf, err_buf_size, err);
        if (head_ref) git_reference_free(head_ref);
        git_signature_free(sig);
        git_tree_free(tree);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    git_oid commit_id;
    err = git_commit_create(&commit_id, repo, "refs/heads/main", sig, sig, NULL, summary, tree, parent_count, parents);

    if (parent) git_commit_free(parent);
    if (head_ref) git_reference_free(head_ref);
    git_signature_free(sig);
    git_tree_free(tree);

    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    git_repository_set_head(repo, "refs/heads/main");

    printf("Added and committed!\n");
    printf("Pushing your new idea..\n");
    fflush(stdout);

    // Remote push
    git_remote *remote = NULL;
    err = git_remote_lookup(&remote, repo, "origin");
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
        git_repository_free(repo);
        git_libgit2_shutdown();
        return err;
    }

    const char *refspec = "refs/heads/main:refs/heads/main";
    git_strarray refspecs = { (char **)&refspec, 1 };
    git_push_options push_opts;
    git_push_options_init(&push_opts, GIT_PUSH_OPTIONS_VERSION);

    err = git_remote_push(remote, &refspecs, &push_opts);
    if (err < 0) {
        format_err(err_buf, err_buf_size, err);
    } else {
        printf("Pushed!\n");
    }

    git_remote_free(remote);
    git_repository_free(repo);
    git_libgit2_shutdown();
    return err;
}
