{"command":"cat <<'EOF' > src/main.rs
use std::env;
use std::ffi::CString;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

extern "C" {
    fn do_git_ops(
        repo_path: *const i8,
        summary: *const i8,
        err_buf: *mut i8,
        err_buf_size: usize,
    ) -> i32;
}

fn log_error(msg: &str) {
    eprintln!(" ERROR eureka > {}", msg);
}

fn get_config_path() -> Option<PathBuf> {
    if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
        if !xdg.trim().is_empty() {
            return Some(PathBuf::from(xdg).join("eureka/config.json"));
        }
    }
    if let Ok(home) = env::var("HOME") {
        if !home.trim().is_empty() {
            return Some(PathBuf::from(home).join(".config/eureka/config.json"));
        }
    }
    None
}

fn parse_repo_from_config(config_path: &Path) -> Option<String> {
    let content = fs::read_to_string(config_path).ok()?;
    let idx = content.find("\"repo\"")?;
    let rest = &content[idx + 6..];
    let colon_idx = rest.find(':')?;
    let rest = &rest[colon_idx + 1..];
    let start_quote = rest.find('"')?;
    let rest = &rest[start_quote + 1..];
    let end_quote = rest.find('"')?;
    Some(rest[..end_quote].to_string())
}

fn print_help() {
    print!(
        "Input and store your ideas without leaving the terminal\n\n\
        Usage: executable [OPTIONS]\n\n\
        Options:\n  \
              --clear-config  Clear your stored configuration\n  \
          -v, --view          View ideas with your $PAGER env variable. If unset use less\n  \
          -h, --help          Print help\n  \
          -V, --version       Print version\n"
    );
}

fn print_version() {
    println!("eureka 2.0.0");
}

fn print_unexpected_arg(arg: &str, usage_sub: &str) -> ExitCode {
    eprintln!(
        "error: unexpected argument '{}' found\n\nUsage: executable {}\n\nFor more information, try '--help'.",
        arg, usage_sub
    );
    ExitCode::from(2)
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let flags: Vec<&str> = args.iter().skip(1).map(|s| s.as_str()).collect();

    if flags.contains(&"-h") || flags.contains(&"--help") {
        print_help();
        return ExitCode::SUCCESS;
    }
    if flags.contains(&"-V") || flags.contains(&"--version") {
        print_version();
        return ExitCode::SUCCESS;
    }

    let mut clear_config = false;
    let mut view = false;
    let mut unknown_arg: Option<&str> = None;

    for flag in &flags {
        match *flag {
            "--clear-config" => clear_config = true,
            "-v" | "--view" => view = true,
            other => {
                if unknown_arg.is_none() {
                    unknown_arg = Some(other);
                }
            }
        }
    }

    if let Some(arg) = unknown_arg {
        let usage = if clear_config {
            "--clear-config"
        } else if view {
            "--view"
        } else {
            "[OPTIONS]"
        };
        return print_unexpected_arg(arg, usage);
    }

    let config_path = match get_config_path() {
        Some(p) => p,
        None => {
            log_error("No such file or directory (os error 2)");
            return ExitCode::SUCCESS;
        }
    };

    if clear_config {
        if config_path.exists() {
            if let Err(e) = fs::remove_file(&config_path) {
                log_error(&e.to_string());
            }
        } else {
            log_error("No such file or directory (os error 2)");
        }
        return ExitCode::SUCCESS;
    }

    if view {
        let repo = match parse_repo_from_config(&config_path) {
            Some(r) => r,
            None => {
                log_error("No such file or directory (os error 2)");
                return ExitCode::SUCCESS;
            }
        };
        let readme_path = format!("{}/README.md", repo);
        let pager = env::var("PAGER")
            .ok()
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "less".to_string());

        let res = Command::new(&pager).arg(&readme_path).status();
        if let Err(e) = res {
            log_error(&e.to_string());
        }
        return ExitCode::SUCCESS;
    }

    // Default flow
    let repo_path = match parse_repo_from_config(&config_path) {
        Some(r) => r,
        None => {
            run_setup(&config_path);
            return ExitCode::SUCCESS;
        }
    };

    run_idea(&repo_path);
    ExitCode::SUCCESS
}

fn run_setup(config_path: &Path) {
    let banner = "\x1b[0m\x1b[33m############################################################\n\
                  ####                  First Time Setup                  ####\n\
                  ############################################################\n\n\
                  This tool requires you to have a repository with a README.md\n\
                  in the root folder. The markdown file is where your ideas\n\
                  will be stored.\n\n\
                  Once first time setup has completed, simply run Eureka again\n\
                  to begin writing down ideas.\n        \n\x1b[0m";
    print!("{}", banner);
    io::stdout().flush().ok();

    let stdin = io::stdin();
    loop {
        print!("\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ");
        io::stdout().flush().ok();

        let mut line = String::new();
        if stdin.read_line(&mut line).is_err() || line.is_empty() {
            break;
        }

        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if !trimmed.starts_with('/') {
            print!("\x1b[0m\x1b[31mPath must be absolute\n");
            io::stdout().flush().ok();
            continue;
        }

        if let Some(parent) = config_path.parent() {
            fs::create_dir_all(parent).ok();
        }
        let json_content = format!("{{\"repo\":\"{}\"}}", trimmed);
        if fs::write(config_path, json_content).is_ok() {
            println!("First time setup complete. Happy ideation!");
        }
        break;
    }
}

fn run_idea(repo_path: &str) {
    let stdin = io::stdin();
    let mut summary = String::new();

    loop {
        print!("\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ");
        io::stdout().flush().ok();

        let mut line = String::new();
        if stdin.read_line(&mut line).is_err() || line.is_empty() {
            return;
        }

        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        summary = trimmed.to_string();
        break;
    }

    let readme_path = format!("{}/README.md", repo_path);

    let editor_var = env::var("EDITOR").ok().filter(|s| !s.trim().is_empty());

    if let Some(editor_cmd) = editor_var {
        let status = Command::new(&editor_cmd).arg(&readme_path).status();
        if let Err(e) = status {
            log_error(&e.to_string());
        }
    } else {
        let mut launched = false;
        for ed in &["nano", "vi", "vim", "ed"] {
            if let Ok(mut child) = Command::new(ed).arg(&readme_path).spawn() {
                launched = true;
                child.wait().ok();
                break;
            }
        }
        if !launched {
            log_error("cannot find binary path");
        }
    }

    println!("Adding and committing your new idea to main..");
    io::stdout().flush().ok();

    let c_repo = match CString::new(repo_path) {
        Ok(c) => c,
        Err(_) => return,
    };
    let c_summary = match CString::new(summary) {
        Ok(c) => c,
        Err(_) => return,
    };

    let mut err_buf = [0i8; 1024];
    let res = unsafe {
        do_git_ops(
            c_repo.as_ptr(),
            c_summary.as_ptr(),
            err_buf.as_mut_ptr(),
            err_buf.len(),
        )
    };

    if res < 0 {
        let c_str = unsafe { std::ffi::CStr::from_ptr(err_buf.as_ptr()) };
        log_error(&c_str.to_string_lossy());
    }
}
EOF"}

