fn print_unexpected_arg(arg: &str, usage_sub: &str) -> ExitCode {
    eprintln!(
        "error: unexpected argument '{}' found\n\nUsage: executable {}\n\nFor more information, try '--help'.",
        arg, usage_sub
    );
    ExitCode::from(2)
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let flags: Vec<&str> = args.iter().skip(1).map(|s| s.as_str()).collect();

    if flags.contains(&"-h") || flags.contains(&"--help") {
        print_help();
        return ExitCode::SUCCESS;
    }
    if flags.contains(&"-V") || flags.contains(&"--version") {
        print_version();
        return ExitCode::SUCCESS;
    }

    let mut clear_config = false;
    let mut view = false;
    let mut unknown_arg: Option<&str> = None;

    for flag in &flags {
        match *flag {
            "--clear-config" => clear_config = true,
            "-v" | "--view" => view = true,
            other => {
                if unknown_arg.is_none() {
                    unknown_arg = Some(other);
                }
            }
        }
    }

    if let Some(arg) = unknown_arg {
        let usage = if clear_config {
            "--clear-config"
        } else if view {
            "--view"
        } else {
            "[OPTIONS]"
        };
        return print_unexpected_arg(arg, usage);
    }

    let config_path = match get_config_path() {
        Some(p) => p,
        None => {
            log_error("No such file or directory (os error 2)");
            return ExitCode::SUCCESS;
        }
    };

    if clear_config {
        if config_path.exists() {
            if let Err(e) = fs::remove_file(&config_path) {
                log_error(&e.to_string());
